'use client';
import {useState} from 'react';
import {HelpVideoAdmin} from '@/components/help-video-admin';
import {HelpAndPending} from '@/components/help-and-pending';
import type {SupabaseClient} from '@supabase/supabase-js';
const rows:Record<string,unknown>[]=[];
const client={from:()=>{let operation='select';let values:Record<string,unknown>={};let id='';const q={select:()=>q,order:()=>q,insert:(v:Record<string,unknown>)=>{operation='insert';values=v;return q;},update:(v:Record<string,unknown>)=>{operation='update';values=v;return q;},delete:()=>{operation='delete';return q;},eq:(_:string,v:string)=>{id=v;return q;},single:async()=>{if(operation==='insert'){id=crypto.randomUUID();rows.push({...values,id});}if(operation==='update')Object.assign(rows.find(r=>r.id===id)!,values);if(operation==='delete')rows.splice(rows.findIndex(r=>r.id===id),1);return {data:{id},error:null};},then:(resolve:(v:unknown)=>unknown)=>Promise.resolve({data:[...rows],error:null}).then(resolve)};return q;},storage:{from:()=>({upload:async()=>({error:null}),remove:async()=>({error:null}),createSignedUrls:async(paths:string[])=>({data:paths.map(path=>({path,signedUrl:'/qa-video.mp4'})),error:null})})}} as unknown as SupabaseClient;
export default function Page(){const [context,setContext]=useState('coordination:wall:');return <main className="p-4"><label>Contexto de teste<select value={context} onChange={e=>setContext(e.target.value)}><option value="coordination:wall:">Coordenação mural</option><option value="mechanic:wall:">Mecânico mural</option><option value="coordination:flights:">Coordenação trilhos</option></select></label><div className="bg-blue-700 p-2"><HelpAndPending client={client} context={context} area="Teste" user="TESTE"/></div><HelpVideoAdmin client={client} requireSignature={async action=>{await action();return true;}}/></main>}
